composio run '
const res = await execute("SLACK_SEND_MESSAGE", { channel: "general", text: "build passed" });
const findTs = (o) => {
  if (o && typeof o === "object") {
    if (typeof o.ts === "string") return o.ts;
    for (const v of Object.values(o)) { const t = findTs(v); if (t) return t; }
  }
  return undefined;
};
const ts = findTs(res);
console.log(JSON.stringify(res, null, 2));
console.log("timestamp:", ts ?? "not found in response");
' 2>&1

